from pathlib import Path
import re
import rasterio
import numpy as np
import torch
from torch.utils.data import Dataset


# ---------------------------------------------------------------------------
# Per-band normalization constants computed from the full SEN12MS subset
# (1167 patch pairs, scenes 21 & 22). Generated by scripts/compute_dataset_stats.py
#
# SAR (Sentinel-1 GRD, dB scale): Z-score per band using empirical mean/std.
#   Using Z-score instead of hardcoded [-25, 0] clip prevents information loss
#   at extreme values (smooth water < -25 dB, urban > 0 dB).
# ---------------------------------------------------------------------------
SAR_MEAN = [-11.476286, -17.751606]   # dB (VV, VH)
SAR_STD  = [3.257546,   3.956914]     # dB (VV, VH)

# ---------------------------------------------------------------------------
# Optical (Sentinel-2): Z-score per band using empirical mean/std.
#   Default bands: B4 (Red), B8 (NIR), B11 (SWIR1), B12 (SWIR2)
#   Rationale: NIR and SWIR are complementary to SAR (vegetation, moisture).
#   B11 raw uint16 range is ~6–91 (small values), so Z-score is critical here.
# ---------------------------------------------------------------------------
OPT_MEAN = [878.379167, 1933.121434, 32.397427, 1912.592565]  # raw uint16
OPT_STD  = [336.91765,  492.114564,  20.41353,  501.811827]   # raw uint16

# ---------------------------------------------------------------------------
# Optical RGB (Sentinel-2 true colour): B4 (Red), B3 (Green), B2 (Blue)
# Band indices (0-indexed): B4=3, B3=2, B2=1
# Normalization: Z-score using Sentinel-2 empirical values for these bands.
# B4 (Red):   mean ~878, std ~337  (same as OPT_MEAN[0]/OPT_STD[0])
# B3 (Green): mean ~1034, std ~292 (empirical from SEN12MS literature)
# B2 (Blue):  mean ~843,  std ~284 (empirical from SEN12MS literature)
# Order here matches band selection [3, 2, 1] → R, G, B
# ---------------------------------------------------------------------------
OPT_RGB_BANDS = [3, 2, 1]   # 0-indexed: B4=Red, B3=Green, B2=Blue
OPT_RGB_MEAN  = [878.379167, 1034.0, 843.0]   # R, G, B
OPT_RGB_STD   = [336.91765,  292.0,  284.0]   # R, G, B


# ---------------------------------------------------------------------------
# SEN12MS patch filename pattern:
# ROIs2017_winter_s1_21_p302.tif
# Group 1: sensor (s1/s2), Group 2: scene_id, Group 3: patch_id
# ---------------------------------------------------------------------------
_PATCH_RE = re.compile(r"ROIs\d+_\w+_(s[12])_(\d+)_p(\d+)\.tif")


def _parse_patch_id(path: Path):
    """Extract (sensor, scene_id, patch_id) from a SEN12MS filename."""
    m = _PATCH_RE.match(path.name)
    if m is None:
        return None
    return m.group(1), m.group(2), m.group(3)


class SEN12MSDataset(Dataset):
    """
    Loads paired SAR (Sentinel-1) and optical (Sentinel-2) patches
    from the SEN12MS dataset subset.

    Directory structure expected:
        root_dir/
          ROIs2017_winter_s1/
            s1_{scene}/
              ROIs2017_winter_s1_{scene}_p{patch}.tif
          ROIs2017_winter_s2/
            s2_{scene}/
              ROIs2017_winter_s2_{scene}_p{patch}.tif

    Args:
        root_dir: Path to the sen12ms-subset directory
        sar_bands: Which SAR bands to load (None = all 2 bands)
        optical_bands: Which optical band indices to load (0-indexed).
                       Default [3, 7, 10, 11] = B4 (Red), B8 (NIR), B11 (SWIR1), B12 (SWIR2).
                       These 4 bands are chosen for SAR-optical complementarity:
                         - SAR is sensitive to vegetation structure → NIR (B8) captures it
                         - SAR is sensitive to soil moisture → SWIR (B11, B12) captures it
                         - RGB-only (old default [3,2,1]) discards the primary S2 advantage.
        normalize: If True, apply per-band Z-score normalization using empirical stats
    """

    def __init__(
        self,
        root_dir,
        sar_bands=None,
        optical_bands=None,
        normalize=True,
    ):
        self.root_dir = Path(root_dir)
        self.sar_bands = sar_bands        # None = load all
        # Default: 4-ch (B4, B8, B11, B12) — SAR-complementary multispectral selection
        self.optical_bands = optical_bands if optical_bands is not None else [3, 7, 10, 11]
        self.normalize = normalize

        # Build a lookup: (scene_id, patch_id) -> s2_path
        s2_lookup = {}
        s2_root = self.root_dir / "ROIs2017_winter_s2"
        for s2_path in s2_root.rglob("*.tif"):
            parsed = _parse_patch_id(s2_path)
            if parsed is None:
                continue
            _, scene_id, patch_id = parsed
            s2_lookup[(scene_id, patch_id)] = s2_path

        # Match every S1 file to its S2 counterpart
        self.samples = []
        s1_root = self.root_dir / "ROIs2017_winter_s1"
        missing_pairs = 0
        for s1_path in sorted(s1_root.rglob("*.tif")):
            parsed = _parse_patch_id(s1_path)
            if parsed is None:
                continue
            _, scene_id, patch_id = parsed
            s2_path = s2_lookup.get((scene_id, patch_id))
            if s2_path is not None:
                self.samples.append((s1_path, s2_path, scene_id, patch_id))
            else:
                missing_pairs += 1

        print(f"Found {len(self.samples)} paired samples")
        if missing_pairs > 0:
            print(f"WARNING: {missing_pairs} S1 files had no matching S2 file")

    def __len__(self):
        return len(self.samples)

    def __getitem__(self, idx):
        s1_path, s2_path, scene_id, patch_id = self.samples[idx]

        with rasterio.open(s1_path) as src:
            if self.sar_bands is not None:
                s1 = src.read(self.sar_bands)
            else:
                s1 = src.read()  # Shape: (2, H, W)

        with rasterio.open(s2_path) as src:
            # rasterio bands are 1-indexed; optical_bands are 0-indexed
            bands_1indexed = [b + 1 for b in self.optical_bands]
            s2 = src.read(bands_1indexed)  # Shape: (len(optical_bands), H, W)

        s1 = s1.astype(np.float32)
        s2 = s2.astype(np.float32)

        if self.normalize:
            # ----------------------------------------------------------------
            # SAR normalization: per-band Z-score using empirical dataset stats.
            # (dB values; empirical range approx [-30, 0] dB in this subset)
            # Z-score preserves information at extremes (water << -25 dB, urban > 0 dB)
            # vs. the old hardcoded [-25, 0] clip which destroyed those values.
            # ----------------------------------------------------------------
            for i in range(min(s1.shape[0], len(SAR_MEAN))):
                s1[i] = (s1[i] - SAR_MEAN[i]) / (SAR_STD[i] + 1e-6)

            # ----------------------------------------------------------------
            # Optical normalization: per-band Z-score using empirical dataset stats.
            # Raw uint16 values (not pre-divided by 10000). Z-score is necessary
            # because B11 SWIR1 has a very different scale (range 6–91) vs B8 NIR
            # (range 544–4551). Simple /10000 normalization leaves B11 near-zero.
            # ----------------------------------------------------------------
            for i in range(min(s2.shape[0], len(OPT_MEAN))):
                s2[i] = (s2[i] - OPT_MEAN[i]) / (OPT_STD[i] + 1e-6)

        s1_tensor = torch.tensor(s1, dtype=torch.float32)
        s2_tensor = torch.tensor(s2, dtype=torch.float32)

        return {
            "sar": s1_tensor,          # (2, H, W) or (sar_bands, H, W)
            "optical": s2_tensor,      # (4, H, W) default (B4+B8+B11+B12)
            "sar_path": str(s1_path),
            "optical_path": str(s2_path),
            "scene_id": scene_id,
            "patch_id": patch_id,
        }